ount_holder_name" value="{{ old('account_holder_name',$account->account_holder_name ?? '') }}" class="rounded-lg border-slate-300"></label><label class="grid gap-1 text-sm">Currency<input name="currency" required value="{{ old('currency',$account->currency ?? 'PHP') }}" maxlength="3" class="rounded-lg border-slate-300"></label><label class="grid gap-1 text-sm">Opening balance<input type="number" step="0.0001" name="opening_balance" required value="{{ old('opening_balance',$account->opening_balance ?? '0.0000') }}" class="rounded-lg border-slate-300">@error('opening_balance')<span class="text-red-600">{{ $message }}</span>@enderror</label><label class="grid gap-1 text-sm">Opening balance date<input type="date" name="opening_balance_date" value="{{ old('opening_balance_date',isset($account) ? $account->opening_balance_date?->toDateString() : '') }}" class="rounded-lg border-slate-300">@error('opening_balance_date')<span class="text-red-600">{{ $message }}</span>@enderror</label><fieldset class="flex flex-wrap gap-4 md:col-span-2"><legend class="mb-2 text-sm font-medium">Allowed operations</legend>@foreach(['allow_receipts'=>'Receipts','allow_disbursements'=>'Disbursements','allow_transfers'=>'Transfers','allow_reconciliation'=>'Reconciliation'] as $field=>$label)<label class="flex items-center gap-2 text-sm"><input type="checkbox" name="{{ $field }}" value="1" @checked(old($field,$account->{$field} ?? ($field!=='allow_reconciliation')))>{{ $label }}</label>@endforeach</fieldset><label class="grid gap-1 text-sm md:col-span-2">Notes<textarea name="notes" class="rounded-lg border-slate-300">{{ old('notes',$account->notes ?? '') }}</textarea></label><div class="md:col-span-2"><button class="rounded-lg bg-blue-700 px-4 py-2 text-sm font-semibold text-white">Save account</button></div></form></x-app-layout>
